from pathlib import Path
import json,hashlib
W=Path(__file__).resolve().parent;ROOT=W.parents[1];D=W/'shibuki_audit';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
paths=[D/'ultimate_arrival_pack02'/f'{form}_readback_{i:02}.png'for i in range(3)for form in('before','after')]+[D/'ultimate_arrival_pack02'/f'partial_{i}.png'for i in(133,136,138,139)]+[D/'ultimate_arrival_sequence01'/f'{form}_id{i}_ordered.png'for i in(2,95,96)for form in('before','after')]
r={'root_actually_viewed':[{'path':p.relative_to(ROOT).as_posix(),'sha256':sha(p)}for p in paths],'arc_sha256':sha(D/'ultimate_arrival_pack02/PL02_U.ARC'),'findings':['최종재추출6판·부분파츠4판·원표3개×2의상6판을 직접 열람했다. 133/136/137/138/139의 머릿결·안경·옷 경계를 각 대기와 비교했고 확정된 추가 절단을 찾지 못했다.','138/139 캡슐 후형의 불필요한 흰 소매는 맨팔로 바뀌었으며 기존 손 최고점과 접점을 유지한다.136의 새 발끝 모듈을1px 내린 결과 전후 양발이 부모바닥22에 맞는다.','130/131/134는 새133을 따르는 효과파생으로 보이고132 순수에너지와140..142 끝부분은 보존했다.'], 'limits':['135는 이전 단순한 그림 그대로이며 미완료이다. 해당 팔 국소 편집은 이미지 도구 자동검토에서 거부되어 이 후보에 대체그림을 넣거나 다른방법으로 우회하지 않았다.','원표95/96에 이어지는95/96 특수 자세의 단색 머리·의상도 이전그림이며 별도 재제작대상이다. 이번 등장8검토 통과를 해당자세완료로 계산하지 않는다.','정적 재추출/원표 표시 검토이며 원게임의 임시 아머 전환·외부효과·실제 착지 발동을 재현했다고 주장하지 않는다.','전체 미술 완료와 사용자 최종 수용은 아니다.'],'runtime_verified':False,'final_user_accepted':False}
p=W/'root_review_checkpoint116.json';assert not p.exists();p.write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n','utf8');print(sha(p))
